import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Home, Search, Heart, MapPin, User } from 'lucide-react';

const NAV_ITEMS = [
  { path: '/home',      label: 'Home',      Icon: Home      },
  { path: '/search',    label: 'Search',    Icon: Search    },
  { path: '/favorites', label: 'Favorites', Icon: Heart     },
  { path: '/nearby',    label: 'Nearby',    Icon: MapPin    },
  { path: '/profile',   label: 'Profile',   Icon: User      },
];

const styles = {
  nav: {
    position: 'fixed', bottom: 0, left: '50%', transform: 'translateX(-50%)',
    width: '100%', maxWidth: 430,
    background: '#1a1a1a',
    borderTop: '1px solid #2a2a2a',
    display: 'flex',
    zIndex: 1000,
  },
  item: (active) => ({
    flex: 1,
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    padding: '10px 0 10px',
    cursor: 'pointer',
    background: 'none',
    border: 'none',
    color: active ? '#FF6B35' : '#666',
    gap: 3,
    transition: 'color 0.2s',
  }),
  label: { fontSize: 10, fontWeight: 600, letterSpacing: 0.2 },
};

export default function BottomNav() {
  const navigate = useNavigate();
  const { pathname } = useLocation();

  return (
    <nav style={styles.nav}>
      {NAV_ITEMS.map(({ path, label, Icon }) => {
        const active = pathname === path || pathname.startsWith(path + '/');
        return (
          <button key={path} style={styles.item(active)} onClick={() => navigate(path)}>
            <Icon size={22} strokeWidth={active ? 2.5 : 1.8} />
            <span style={styles.label}>{label}</span>
          </button>
        );
      })}
    </nav>
  );
}
